export class NewCard {

    public title : string;
    public description : string;
    public imageLarge : string;
    public imageOriginal : string;
    public imagePortrait : string;
    public imageLandscape : string;
    public imageTiny : string;


    constructor(
    ){
        this.title = "";
        this.description = "";
        this.imageLarge = "";
        this.imageOriginal = "";
        this.imagePortrait = "";
        this.imageLandscape = "";
        this.imageTiny = "";
    }
}
